{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Not Enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server access logging enabled, which prevents auditing of requests made to the bucket and hinders incident response."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket Versioning Disabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "LOW",
      "explanation": "Versioning is not enabled on the S3 bucket. This means that if objects are accidentally deleted or overwritten, they cannot be recovered."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket Encryption Using KMS Not Configured",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly configure encryption using AWS Key Management Service (KMS). While default encryption might apply, explicit configuration ensures data at rest is encrypted with customer-managed keys or SSE-KMS as per best practices for sensitive admin dashboards."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "admin_dashboard" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_versioning" "admin_dashboard_versioning" {
  bucket = aws_s3_bucket.admin_dashboard.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "admin_dashboard_encryption" {
  bucket = aws_s3_bucket.admin_dashboard.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "admin_dashboard_logging" {
  bucket        = aws_s3_bucket.admin_dashboard.id
  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "log/"
}

